import React, { useState } from 'react';
import axios from 'axios';
import './App.css';

function App() {
  const [word, setWord] = useState('');
  const [haiku, setHaiku] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const response = await axios.post('http://localhost:5000/generate-haiku', {
        word: word
      });
      setHaiku(response.data.haiku);
    } catch (err) {
      setError('Failed to generate haiku. Please try again.');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="App">
      <header className="App-header">
        <h1>Haiku Generator</h1>
        <form onSubmit={handleSubmit} className="haiku-form">
          <input
            type="text"
            value={word}
            onChange={(e) => setWord(e.target.value)}
            placeholder="Enter a word..."
            required
          />
          <button type="submit" disabled={loading}>
            {loading ? 'Generating...' : 'Generate Haiku'}
          </button>
        </form>

        {error && <p className="error">{error}</p>}

        {haiku && (
          <div className="haiku-display">
            {haiku.split('\n').map((line, index) => (
              <p key={index}>{line}</p>
            ))}
          </div>
        )}
      </header>
    </div>
  );
}

export default App;
